def test_get_organization(self):
    with patch.object(main, 'CONFIG', (self.assets / Path('config.ini')).absolute()):
        result = get_organization()
        self.assertIsNotNone(result)
        self.assertEqual(result.id, 'org_id23423ds')
        self.assertEqual(result.name, 'Safety CLI Org')

def get_organization() ->Optional[Organization]:
    config = configparser.ConfigParser()
    config.read(CONFIG)

    if not config.has_section("organization"):
        return None

    org_section = dict(config.items("organization"))

    if "id" in org_section and "name" in org_section:
        return Organization(id=org_section["id"], name=org_section["name"])

    return None
